    delta={'report_type':'stage79_factor_iteration_pool_delta','generated_at':now,'round_name':weight['round_name'],'source_paths':{'factor_iteration_pool':str(EV/'factor_iteration_pool.json'),'factor_lineage':str(EV/'factor_lineage.json'),'regime_weight_map_phase1':str(WM/'regime_weight_map_phase1.json'),'greenfield_current_factor_leaders':str(GREEN/'current_factor_leaders.json'),'greenfield_factor_pool_snapshot':str(GREEN/'factor_pool_snapshot.json'),'stage78_control_sync':str(EV/'current_combo_stage78_control_sync.json')},'source_mtimes':{'factor_iteration_pool':mt(EV/'factor_iteration_pool.json'),'factor_lineage':mt(EV/'factor_lineage.json'),'regime_weight_map_phase1':mt(WM/'regime_weight_map_phase1.json'),'greenfield_current_factor_leaders':mt(GREEN/'current_factor_leaders.json'),'greenfield_factor_pool_snapshot':mt(GREEN/'factor_pool_snapshot.json'),'stage78_control_sync':mt(EV/'current_combo_stage78_control_sync.json')},'canonical_current_combo_factor_ids':current_ids,'greenfield_extension_factor_ids':green_ids,'pool_summary_snapshot':pool.get('pool_summary') or {},'prior_stage78_signal':stage77.get('stage77_signal') or {},'stage79_action':'refresh iteration pool delta, retain canonical release combo, carry greenfield candidates as watchlist only, then rerun replay/portfolio/nested/walkforward/independent holdout evidence'}
    lineage_delta={'report_type':'stage79_factor_lineage_delta','generated_at':now,'round_name':weight['round_name'],'source_paths':delta['source_paths'],'source_mtimes':delta['source_mtimes'],'canonical_current_combo_factor_ids':current_ids,'greenfield_extension_factor_ids':green_ids,'prior_lineage_keys':sorted(lineage.keys())[:100] if isinstance(lineage,dict) else [],'lineage_update':'stage79 extends stage77 release continuation with fresh pool/lineage delta and explicit no-promotion guard for greenfield watchlist until independent OOS improves'}
